var terraformLogLevelFilter = (line) => {
  if (line.indexOf("Plan:") >= 0) {
    const splitted = line.split("Plan:");
    const prePlan = splitted[0];
    const postPlan = "Plan:" + splitted.slice(1).join();
    return [
      { level: "verbose", line: prePlan },
      { level: "info", line: postPlan }
    ];
  } else if (line.indexOf("Initializing the backend") >= 0 || line.indexOf("Initializing provider plugins") >= 0 || line.indexOf("Installed") >= 0 || line.indexOf("Terraform state has been successfully unlocked") >= 0 || line.indexOf("Acquiring state lock") >= 0 || line.indexOf("Modifications complete") >= 0 || line.indexOf("Creation complete") >= 0 || line.indexOf("Apply complete") >= 0 || line.indexOf("Destruction complete") >= 0 || line.indexOf("Destroy complete") >= 0) {
    return [{ level: "info", line }];
  }
  return [{ level: "verbose", line }];
};
var MAX_RETRIES2 = Number(process.env.MAX_RETRIES || "5");
