var extractValueFromEach = (forEach) => {
  const varDict = exportTerraformVars();
  if (forEach.match(/\$\{toset\((.*)\)\}/)) {
    forEach = forEach.split("toset(")[1].split(")")[0];
  } else if (forEach.match(/\$\{tomap\((.*)\)\}/)) {
    forEach = forEach.split("tomap(")[1].split(")")[0];
  } else if (forEach.match(/\$\{tolist\((.*)\)\}/)) {
    forEach = forEach.split("tolist(")[1].split(")")[0];
  } else if (forEach.match(/\$\{(.*)\}/)) {
    forEach = forEach.split("{")[1].split("}")[0];
  }
  if (forEach.startsWith("var.")) {
    const variable = forEach.split("var.")[1].replace("?", "").trim();
    if (varDict[variable] != null) {
      const value = JSON.parse(varDict[variable]);
      return value;
    }
  }
  return forEach;
};
