async function verifyTerraformChanges() {
  const stackDir = getEnvVariable("STACK_DIR");
  try {
    const state3 = await getTerraformState(stackDir);
    const TargetRoleBoundary = getEnvVariable("TARGET_ROLE_BOUNDARY");
    let shouldDeleteRoles = false;
    const roleDefinitionIds = [];
    for (const resource of state3.resources) {
      if (resource.type === "azurerm_role_definition") {
        for (const instance of resource.instances) {
          const scope2 = instance.attributes.scope;
          if (scope2.startsWith("/providers")) {
            if (scope2 !== TargetRoleBoundary) {
              logger.warn("Existing scope, does not match new scope");
              logger.verbose(JSON.stringify(instance));
              roleDefinitionIds.push(instance.attributes.role_definition_id);
              shouldDeleteRoles = true;
              break;
            }
          }
        }
      }
    }
    if (shouldDeleteRoles) {
      logger.info(
        "Deleting existing event subscriptions and roles because target role boundary is changed"
      );
      await deleteTargetEventSubscriptions();
      for (const roleDefinitionId of roleDefinitionIds) {
        await deleteTargetRoleAssignments(roleDefinitionId);
      }
    }
  } catch (e) {
    logger.warn("Couldn't verify terraform state");
    logger.verbose(e);
  }
}

